["triggers"] = {
{
["trigger"] = {
["use_absorbMode"] = true,
["genericShowOn"] = "showOnActive",
["use_unit"] = true,
["customIcon"] = "function()\n    return aura_env.icon\nend\n\n\n\n\n\n\n\n",
["use_cloneId"] = true,
["debuffType"] = "HELPFUL",
["custom_hide"] = "custom",
["type"] = "custom",
["duration"] = "3",
