["怒气药水 "] = {
["iconSource"] = 1,
["parent"] = "团本药剂使用",
["adjustedMax"] = "",
["customText"] = "function(...)    \n    local str,sid,t\n    sid=6612\n    for i=1,40 do \n        local buffName, icon, count, debuffType, duration, expirationTime, caster, canStealOrPurge, _ , spellId, _, _, casterIsPlayer, nameplateShowAll =UnitBuff(\"player\",i) \n        if buffName and spellId == sid then \n            \n            t = -1*(GetTime()-expirationTime)\n            if t>=60 then\n                return math.ceil(t/60) ..\" m\"\n            elseif t >0 and  t <60 then \n                return math.floor(t) ..\" s\"\n            else\n                return\n            end      \n        end \n    end\n    \n    \nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["customTextUpdate"] = "update",
["url"] = "https://wago.io/y7qMWv4rn/8",
["actions"] = {
["start"] = {
["custom"] = "local e = aura_env \nlocal itemid=5631\nlocal itemname=GetItemInfo(itemid)\nif not _G[e.id..\"Button\"] then \n    local region = WeakAuras.GetRegion(e.id) \n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region, \"SecureActionButtonTemplate\") \n    e.btn:RegisterForClicks(\"LeftButtonUp\", \"RightButtonUp\")\n    e.btn:SetAllPoints(region) \nend \nlocal btn = _G[e.id..\"Button\"] \n\nbtn:SetAttribute(\"type1\", \"item\")\nbtn:SetAttribute(\"type2\", \"item\")\nbtn:SetAttribute(\"item\",\"怒气药水\")\nbtn:SetScript(\"OnEnter\", function(self)               \n        GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\") \n        GameTooltip:SetText(GetItemInfo(itemid), 0, 1, 0, 1, 1)\n        \nend)\nbtn:SetScript(\"OnLeave\", function(self) GameTooltip:Hide() end)\nbtn:Show()",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local e = aura_env \nif  _G[e.id..\"Button\"] then \n    local btn = _G[e.id..\"Button\"] \n    btn:Hide()\nend ",
["do_custom"] = true,
},
