["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["do_custom"] = true,
["custom"] = "local chatFrame = SELECTED_DOCK_FRAME\nlocal inputbox = chatFrame.editBox\nlocal e = aura_env\nif not _G[e.id..\"Button\"] then \n    local region = WeakAuras.GetRegion(e.id) \n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region) \n    e.btn:RegisterForClicks(\"AnyUp\",\"AnyDown\")\n    e.btn:SetScript(\"OnMouseUP\", function(self, button)\n            --左键打开主菜单 右键打开商城\n            if button == \"RightButton\" then\n                ToggleStoreUI()\n            else\n                ToggleFrame(GameMenuFrame)\n            end\n            region:SetAlpha(1)\n    end)\n    e.btn:SetScript(\"OnMouseDown\", function(self)\n            region:SetAlpha(0.5)\n    end)\n    e.btn:SetScript(\"OnEnter\",function(self)\n            GameTooltip:SetOwner(self, 'ANCHOR_TOP', 0,1)\n            GameTooltip:AddLine(\"|cffFFffFF左键:|r \".._G.MAINMENU_BUTTON)\n            GameTooltip:AddLine(\"|cffFFffFF右键:|r 商城\")\n            GameTooltip:AddDoubleLine(\" \")\n            local _, _, homePing, worldPing = GetNetStats()\n            GameTooltip:AddDoubleLine(\"每秒帧数: \", floor(GetFramerate())..FPS_ABBR)\n            GameTooltip:AddDoubleLine(\" \")\n            GameTooltip:AddDoubleLine(\"本地延迟: \", floor(homePing)..MILLISECONDS_ABBR)\n            GameTooltip:AddDoubleLine(\"世界延迟: \", floor(worldPing)..MILLISECONDS_ABBR)\n            GameTooltip:Show()\n            region:SetScale(1.05)\n    end)\n    e.btn:SetScript(\"OnLeave\",function(self)\n            GameTooltip:Hide()\n            region:SetScale(1)\n    end)\n    e.btn:SetAllPoints(region)\nend\n\n\n\n\n\n\n\n\n",
},
},
