["events"] = "CHAT_MSG_COMBAT_XP_GAIN",
["custom"] = "\nfunction(event, arg1, arg2, ...)\n    if aura_env.inInstance then\n        if aura_env.MobCount == nil then\n            aura_env.MobCount =  0\n        end\n        if aura_env.XPCount == nil then\n            aura_env.XPCount =  0\n        end\n        aura_env.XPCount = aura_env.XPCount + string.match(arg1, '%d+')\n        aura_env.MobCount = aura_env.MobCount + 1\n    end\nend",
