{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["duration"] = "1",
["event"] = "Chat Message",
["subeventPrefix"] = "SPELL",
["events"] = "PLAYER_ENTERING_WORLD",
["unevent"] = "timed",
["custom"] = "function(event, arg1, arg2, ...)\n    if aura_env.config[\"LogInDefault\"] then\n        if aura_env.XPCountString ~= nil and string.len(aura_env.XPCountString) > 0 then\n            print(aura_env.XPCountString)\n        end\n        if aura_env.MobCountString ~= nil and string.len(aura_env.MobCountString) > 0 then\n            print(aura_env.MobCountString)\n        end\n        if aura_env.RepCountString ~= nil and string.len(aura_env.RepCountString) > 0 then\n            print(aura_env.RepCountString)\n        end\n        if aura_env.HonorString ~= nil and string.len(aura_env.HonorCount) > 0 then\n            print(aura_env.HonorString)\n        end\n        if aura_env.TimerString ~= nil and string.len(aura_env.TimerString) > 0 then\n            print(aura_env.TimerString)\n        end\n    end\n    if aura_env.config[\"LogInParty\"] then\n        if aura_env.XPCountString ~= nil and string.len(aura_env.XPCountString) > 0 then\n            SendChatMessage(aura_env.XPCountString, \"PARTY\")\n        end\n        if aura_env.MobCountString ~= nil and string.len(aura_env.MobCountString) > 0 then\n            SendChatMessage(aura_env.MobCountString, \"PARTY\")\n        end\n        if aura_env.RepCountString ~= nil and string.len(aura_env.RepCountString) > 0 then\n            SendChatMessage(aura_env.RepCountString, \"PARTY\")\n        end\n        if aura_env.HonorString ~= nil and string.len(aura_env.HonorCount) > 0 then\n            SendChatMessage(aura_env.HonorString, \"PARTY\")\n        end\n        if aura_env.TimerString ~= nil and string.len(aura_env.TimerString) > 0 then\n            SendChatMessage(aura_env.TimerString, \"PARTY\")\n        end\n    end\n    local name, standing, min, max, value = GetWatchedFactionInfo()\n    aura_env.RepName = name\n    aura_env.RepValue = value\n    local inInstance, instanceType = IsInInstance()\n    aura_env.inInstance = (instanceType == \"party\" or instanceType == \"raid\" or instanceType == \"pvp\")\n    aura_env.StartingTime = GetTime()\n    aura_env.MobCount =  0\n    aura_env.RepCount = 0\n    aura_env.XPCount =  0\n    aura_env.HonorCount =  0\n    aura_env.percentXP =  0\n    aura_env.XPCountString = ''\n    aura_env.MobCountString = ''\n    aura_env.RepCountString = ''\n    aura_env.TimerString = ''\n    aura_env.HonorString = ''\n    aura_env.players = {}\n    aura_env.Factions = {}\n    local numFactions = GetNumFactions()\n    for i = 0,numFactions - 1 do\n        local name, description, standingId, bottomValue, topValue, earnedValue, atWarWith,\n        canToggleAtWar, isHeader, isCollapsed, hasRep, isWatched, isChild = GetFactionInfo(i)\n        if not isHeader then\n            aura_env.Factions[i] = {name, earnedValue, earnedValue}\n        end\n    end\nend",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
},
