["custom"] = "function(event, arg1, arg2, arg3, ...)\n    for key, value in pairs(aura_env.Factions) do\n        local name, description, standingId, bottomValue, topValue, earnedValue, atWarWith,\n        canToggleAtWar, isHeader, isCollapsed, hasRep, isWatched, isChild = GetFactionInfo(key)\n        if name == aura_env.Factions[key][1] then\n            aura_env.Factions[key][3] = earnedValue\n        end\n    end\nend",
