["sparkHidden"] = "NEVER",
["id"] = "经验值显示-60级隐藏",
["spark"] = false,
["frameStrata"] = 1,
["anchorFrameType"] = "SCREEN",
["desc"] = "Created by Luxthos & Daemoos\nwww.twitch.tv/luxthos",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local this = aura_env\n\nthis.timerHandler = this.timerHandler or nil\n\nthis.GetSavedVars = function()\n    local WAS = this.saved or {}\n    this.saved = WAS\n    \n    WAS.session = WAS.session or {}\n    \n    WAS.session.gainedXP = WAS.session.gainedXP or 0\n    WAS.session.lastXP = WAS.session.lastXP or UnitXP(\"player\")\n    WAS.session.maxXP = WAS.session.maxXP or UnitXPMax(\"player\")\n    WAS.session.startTime = WAS.session.startTime or time()\n    WAS.session.realTotalTime = WAS.session.realTotalTime or 0\n    WAS.session.realLevelTime = WAS.session.realLevelTime or 0\n    WAS.session.lastTimePlayedRequest = WAS.session.lastTimePlayedRequest or 0\n    \n    return WAS\nend\n\nthis.IsXPUserDisabled = IsXPUserDisabled or function() return false end\n\nthis.GetMaxLevel = function(exp)\n    exp = exp or GetExpansionLevel()\n    \n    return min(GetMaxPlayerLevel(), GetMaxLevelForExpansionLevel(exp))\nend\n\nthis.level = UnitLevel(\"player\")\nthis.isPlayerMaxLevel = this.level >= this.GetMaxLevel()\n\nlocal GetNumQuestLogEntries = C_QuestLog.GetNumQuestLogEntries or GetNumQuestLogEntries\nlocal GetQuestIDForLogIndex = C_QuestLog.GetQuestIDForLogIndex or function(i)\n    return select(8, GetQuestLogTitle(i))\nend\nlocal SelectQuestLogEntry = SelectQuestLogEntry or function() end\nlocal IsQuestComplete = C_QuestLog.IsComplete or IsQuestComplete\nlocal QuestReadyForTurnIn = C_QuestLog.ReadyForTurnIn or function() return false end\n\nthis.UpdateQuestXP = function()\n    local numQ = GetNumQuestLogEntries()\n    local questXP = 0\n    local completeXP = 0\n    local incompleteXP = 0\n    local questID, rewardXP\n    local selQ = 0\n    local GetQuestLogRewardXP = GetQuestLogRewardXP or function()\n        return 0\n    end\n    \n    if GetQuestLogSelection then\n        selQ = GetQuestLogSelection()\n    end\n    \n    for i = 1, numQ do\n        SelectQuestLogEntry(i)\n        questID = GetQuestIDForLogIndex(i)\n        \n        if questID > 0 then\n            rewardXP = GetQuestLogRewardXP(questID) or 0\n            \n            if rewardXP > 0 then\n                questXP = questXP + rewardXP\n                \n                if IsQuestComplete(questID) or QuestReadyForTurnIn(questID) then\n                    completeXP = completeXP + rewardXP\n                else\n                    incompleteXP = incompleteXP + rewardXP\n                end\n            end\n        end\n    end\n    \n    this.questXP = questXP\n    this.completeXP = completeXP\n    this.incompleteXP = incompleteXP\n    \n    if selQ > 0 then\n        SelectQuestLogEntry(selQ)\n        StaticPopup_Hide(\"ABANDON_QUEST\")\n        StaticPopup_Hide(\"ABANDON_QUEST_WITH_ITEMS\")\n        \n        if QuestLogControlPanel_UpdateState then\n            local SetAbandonQuest = SetAbandonQuest or function() end\n            \n            QuestLogControlPanel_UpdateState()\n            SetAbandonQuest()\n        end\n    end\nend\n\nthis.UpdateQuestXP()\n\nthis.round = function(num, decimals)\n    local mult = 10^(decimals or 0)\n    \n    return Round(num * mult) / mult\nend\n\n-- 统一数值格式化：支持 中式 / 西式 切换\nthis.FormatLargeNumberSmart = function(num)\n    num = tonumber(num) or 0\n    \n    -- 如果开启“东方格式”\n    if this.config and this.config.useCNNumberFormat then\n        local str = tostring(math.floor(num))\n        local result = \"\"\n        \n        while #str > 4 do\n            result = \",\" .. str:sub(-4) .. result\n            str = str:sub(1, -5)\n        end\n        \n        return str .. result\n    end\n    \n    -- 否则使用暴雪原生西方格式\n    return FormatLargeNumber(num)\nend\n\n\n--新增东安4位数分割\nthis.FormatLargeNumberCN = function(num)\n    num = tonumber(num) or 0\n    local str = tostring(math.floor(num))\n    local result = \"\"\n    \n    while #str > 4 do\n        result = \",\" .. str:sub(-4) .. result\n        str = str:sub(1, -5)\n    end\n    \n    return str .. result\nend\n\nthis.FormatTime = function(time, format)\n    if time <= 59 then\n        return \"< 1分钟\"\n    end\n    \n    local d, h, m, s = ChatFrame_TimeBreakDown(time)\n    local t = format or \"%d天 %h时 %m分\" -- 中文默认格式\n    \n    local pad = function(v)\n        return v < 10 and \"0\" .. v or v\n    end\n    \n    local subs = {\n        [\"%%D天\"] = d > 0 and (pad(d) .. \"天\") or \"\",\n        [\"%%d天\"] = d > 0 and (d .. \"天\") or \"\",\n        \n        [\"%%H时\"] = (d > 0 or h > 0) and (pad(h) .. \"时\") or \"\",\n        [\"%%h时\"] = (d > 0 or h > 0) and (h .. \"时\") or \"\",\n        \n        [\"%%M分\"] = pad(m) .. \"分\",\n        [\"%%m分\"] = m .. \"分\",\n        \n        [\"%%S秒\"] = pad(s) .. \"秒\",\n        [\"%%s秒\"] = s .. \"秒\",\n    }\n    \n    for k, v in pairs(subs) do\n        t = t:gsub(k, v)\n    end\n    \n    -- 关键：完全复刻 Luxthos 原版“0值裁剪”行为（中文适配版）\n    return strtrim(\n        t\n        :gsub(\"^%s*0天\", \"\")\n        :gsub(\"^%s*0时\", \"\"),\n        \" :/-|\"\n    )\nend\n\nthis.tickerRTP = this.tickerRTP or nil\nthis.requestingTimePlayed = false\n\nthis.ClearTickerRTP = function()\n    if this.tickerRTP then\n        this.tickerRTP:Cancel()\n        this.tickerRTP = nil\n    end\n    \n    this.requestingTimePlayed = false\nend\n\nthis.RequestTimePlayed = function()\n    if not this.requestingTimePlayed then\n        this.ClearTickerRTP()\n        \n        this.requestingTimePlayed = true\n        \n        this.tickerRTP = C_Timer.NewTimer(0.5, function() RequestTimePlayed() end)\n    end\nend\n\nthis.customTexts = {\n    c1 = \"等级 \" .. this.level,\n    c2 = \"0 / 0 (0)\",\n    c3 = \"0%\",\n    c4 = \"\",\n    c5 = \"\",\n    c6 = \"\",\n    c7 = \"\",\n}\n\nthis.UpdateCustomTexts = function(state)\n    local c1, c2, c3, c4, c5, c6, c7\n    local s = state or this.state\n    local cfg = this.config\n    local round = this.round\n    local isMaxLevel = this.isPlayerMaxLevel\n    \n    c1 = \"等级 \" .. (s.level or UnitLevel(\"player\"))\n    \n    if isMaxLevel then\n        c2 = \"满级\"\n    else\n        -- c2 = string.format(\"%s / %s (%s)\", FormatLargeNumber(s.currentXP or 0), FormatLargeNumber(s.totalXP or 0), FormatLargeNumber(s.remainingXP or 0))\n        -- c2 = string.format(\"%s / %s (%s)\",this.FormatLargeNumberCN(s.currentXP or 0),this.FormatLargeNumberCN(s.totalXP or 0),this.FormatLargeNumberCN(s.remainingXP or 0))\n        c2 = string.format(\"%s / %s (%s)\",this.FormatLargeNumberSmart(s.currentXP or 0),this.FormatLargeNumberSmart(s.totalXP or 0),this.FormatLargeNumberSmart(s.remainingXP or 0))\n    end\n    \n    c3 = string.format(\"%s%%\" .. ((s.percentcomplete or 0) > 0 and \" (%s%%)\" or \"\"), round(s.percentXP or 0, 1), round(s.totalpercentcomplete or 0, 1))\n    \n    if not isMaxLevel then\n        if cfg[\"showxphour-text\"] then\n            local hourlyXP = s.hourlyXP or 0\n            \n            c4 = string.format(\"即将升级: %s (%s%s 经验/小时)\", s.timeToLevelText or \"\", hourlyXP >= 10000 and round(hourlyXP / 10000, 2) or FormatLargeNumber(hourlyXP), hourlyXP >= 10000 and \"万\" or \"\")\n        end\n        \n        if cfg[\"questrested-text\"] then\n            c5 = string.format(\"已完成: |cFFFF9700%s%%|r - 休息: |cFF4F90FF%s%%|r\", round(s.percentcomplete or 0, 1), round(s.percentrested or 0, 1))\n        end\n    end\n    \n    if cfg[\"leveltime-text\"] then\n        if isMaxLevel then\n            c6 = \"游戏时长: \" .. (s.totalTimeText or \"\")\n        else\n            c6 = \"当前时长: \" .. (s.levelTimeText or \"\")\n        end\n    end\n    \n    if cfg[\"sessiontime-text\"] then\n        c7 = \"会话时长: \" .. (s.sessionTimeText or \"\")\n    end\n    \n    this.customTexts = {\n        c1 = c1,\n        c2 = c2,\n        c3 = c3,\n        c4 = c4,\n        c5 = c5,\n        c6 = c6,\n        c7 = c7,\n    }\nend",
