["useAdjustedMax"] = false,
["mirror"] = false,
["sparkWidth"] = 10,
["foregroundTexture"] = "Textures\\SpellActivationOverlays\\Eclipse_Sun",
["borderInFront"] = true,
["authorOptions"] = {
{
