["glow_action"] = "show",
},
["init"] = {
["custom"] = "aura_env.healInfo = {}\naura_env.healer = {\"player\"}\naura_env.healerFlag = {}\naura_env.healerFlag[\"player\"] = true",
["do_custom"] = true,
