["unit"] = "player",
["customDuration"] = "function()\n    return 1.9, (aura_env.tickTimestamp or GetTime()) + 1.9\nend",
["unevent"] = "timed",
["custom"] = "function(event, unit, power)\n    if not (\"player\" == unit and \"MANA\" == power) then\n        return\n    end\n    \n    local currentMana = UnitPower(unit, Enum.PowerType.Mana, true)\n    local maxMana = UnitPowerMax(unit, Enum.PowerType.Mana, true)\n    local prevMana = aura_env.prevMana or maxMana\n    local ts = GetTime()\n    local tickTimestamp = aura_env.tickTimestamp or ts\n    \n    local function GetMP5FromGear(unit)\n        local mp5 = 0;\n        for i = 1, 18 do\n            local itemLink = GetInventoryItemLink(unit, i);\n            if itemLink then\n                local stats = GetItemStats(itemLink);\n                if stats then\n                    -- This returns (mp5 - 1)?\n                    local statMP5 = stats[\"ITEM_MOD_POWER_REGEN0_SHORT\"];\n                    if (statMP5) then\n                        mp5 = mp5 + statMP5 + 1;\n                    end\n                end\n            end\n        end    \n        return mp5;\n    end\n    \n    aura_env.prevMana = currentMana\n    \n    if currentMana >= maxMana then\n        -- Mana is full\n        return\n    elseif currentMana <= prevMana then\n        -- Mana used\n        if (ts - tickTimestamp) < 2 then\n            -- Tick in progress or first tick\n            return\n        end\n        aura_env.tickTimestamp = (ts - ts % 2) + (tickTimestamp % 2)\n    else\n        -- Mana replenished\n        base, casting = GetManaRegen()\n        manaPerTick = base * 2 + GetMP5FromGear(unit) * 0.4\n        deviation = currentMana - prevMana - manaPerTick\n        -- print(deviation)\n        -- 大水引发的误差\n        if (deviation > 280) then\n            deviation = deviation - 283\n        end\n        -- Not mana from SPIRIT!\n        if (deviation < -1) or (deviation > 1.4) then\n            return\n        end        \n        aura_env.tickTimestamp = ts\n    end    \n    \n    return true\nend",
