["customText"] = "\nfunction(...)\n    local str\n    local time\n    local hasMHEnchant, MHExpiration, MHCharges, MHEnchantID, hasOHEnchant, OHExpiration, OHCharges, OHEnchantID = GetWeaponEnchantInfo()\n    if hasMHEnchant then\n        time=MHExpiration/1000           \n        if time >=60 then\n            aura_env.region:SetGlow(false)\n            return math.ceil(time/60) ..\" m\"\n        elseif time >0 and  time <60 then  \n            --     aura_env.region:SetGlow(true)\n            local color\n            if time >=30 then\n                color = \"|cffffffff\"\n            else\n                color = \"|cffff0000\"\n            end\n            return color .. math.floor(time) ..\" s\"\n        else\n            return\n        end      \n    else\n        -- aura_env.region:SetGlow(true)\n        return\n    end   \nend",
