["triggers"] = {
{
["trigger"] = {
["unit"] = "player",
["customIcon"] = "function (...)\n    local mh = GetInventoryItemLink(\"player\", 16)\n    if mh then\n        local hasMHEnchant, MHExpiration, MHCharges, MHEnchantID, hasOHEnchant, OHExpiration, OHCharges, OHEnchantID = GetWeaponEnchantInfo()\n        if hasMHEnchant then\n            for k,v in pairs(aura_env.list) do\n                if MHEnchantID==k then                      \n                    return v[2]\n                end\n            end          \n        else\n            --  aura_env.region:SetGlow(true)\n            return select(10, GetItemInfo(mh)) \n        end        \n    end\nend",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["spellIds"] = {
},
["event"] = "Health",
["customStacks"] = "function (...)    \n    local mh = GetInventoryItemLink(\"player\", 16)\n    if mh then\n        local hasMHEnchant, MHExpiration, MHCharges, MHEnchantID, hasOHEnchant, OHExpiration, OHCharges, OHEnchantID = GetWeaponEnchantInfo()\n        if hasMHEnchant and MHCharges then\n            return MHCharges\n        else\n            return \"\"           \n        end        \n    end\nend",
["customDuration"] = "function() \n    --  print(1)\n    local mh = GetInventoryItemLink(\"player\", 16)\n    if mh then\n        local hasMHEnchant, MHExpiration, MHCharges, MHEnchantID, hasOHEnchant, OHExpiration, OHCharges, OHEnchantID = GetWeaponEnchantInfo()\n        if hasMHEnchant then\n            return MHExpiration\n        end\n    end\nend",
["customName"] = "function ()\n    \n    local    className, classFilename, classID = UnitClass(\"player\") \n    if classID==1 then --战士\n        local mh = GetInventoryItemLink(\"player\", 16)\n        local _, _, _, _, _, _, itemType,stype = GetItemInfo(mh)\n        \n        if mh  and (itemType ==\"拳套\" or itemType ==\"单手锤\" or itemType ==\"双手锤\" )then        \n            return GetItemCount(12643)    \n        else\n            return GetItemCount(12404)     \n        end\n        \n    elseif classID == 4 then --盗贼\n        local mh = GetInventoryItemLink(\"player\", 16)\n        local _, _, _, _, _, _, itemType,stype = GetItemInfo(mh)\n        \n        if mh  and (itemType ==\"拳套\" or itemType ==\"单手锤\" or itemType ==\"双手锤\" )then        \n            return GetItemCount(12643)    \n        else\n            return GetItemCount(12404)\n            end\n        elseif classID==8   or classID==9 then  --法师，术士\n            return GetItemCount(20749) \n        elseif   classID==2 or  classID==7  or  classID==11  or classID==5 then  --圣骑 萨满 德鲁伊  牧师\n            return GetItemCount(20748) \n        end\n        \n    end",
["custom"] = "function( event, ...)\n    if event == \"PLAYER_ENTERING_WORLD\" or event == \"UNIT_INVENTORY_CHANGED\" then --doesn't return valid durations without C_Timer    \n        \n        C_Timer.After(0.05, function()\n                WeakAuras.ScanEvents(\"ITEM_ENCH_TG\")            end\n        )        \n    elseif event == \"ITEM_ENCH_TG\" and not WeakAuras.IsOptionsOpen() then\n        \n        \n        --    print( itemType )\n        --   print (mh)\n        \n        local oh = GetInventoryItemLink(\"player\", 16)       \n        local _, _, _, _, _, _, itemType,stype = GetItemInfo(oh)\n        if oh  and  itemType ==\"单手锤\" then        \n            \n        end\n        \n        if oh then     \n            \n            return true  \n        end\n    end\nend",
