["outline"] = "OUTLINE",
["parent"] = "实用功能-2026.06.08",
["displayText"] = "%c",
["customText"] = "function()\n    --合成出aura_env.config里面的配置变量名称，并返回该值\n    function RN(name)\n        if(type(name)~='string')\n        then\n            return nil    \n        end\n        \n        local ac = aura_env.config\n        local SNV = 'EMPS.' --本WA的配置参数前缀缩写\n        local ccc = ac[SNV..name]\n        return ccc\n    end\n    local DisplayMoney = RN('DisplayMoney')\n    local Info = RN('PotionGroup')\n    local SN=EMPS --本WA的全局变量前缀缩写\n    local Info = RN('PotionGroup')\n    \n    function FindPotionMoney(PotionName)\n        if(PotionName==nil)\n        then\n            return 0    \n        end\n        \n        --print('药品名称',PotionName)\n        for k,v in pairs (Info)do\n            --print(PotionName,v.Name,v.MONEY)\n            if(PotionName == v.Name)then\n                \n                return v.MONEY    \n            end\n        end\n        return 0\n    end\n    --返回玩家职业\n    function GetPlayerClass(Name)\n        local playerclass=''\n        local index=1\n        local gp=''\n        for unit in WA_IterateGroupMembers() do\n            --查询玩家的信息\n            local Pname, rank, subgroup, level, class, fileName, \n            zone, online, isDead, role, isML, combatRole=GetRaidRosterInfo(index)\n            if(Pname== Name)\n            then\n                \n                playerclass =  tostring(subgroup)..'队的'..class\n            end\n            index = index+1\n        end\n        \n        return playerclass\n    end\n    \n    local AlwaysRefresh=RN('AlwaysRefresh')\n    --print(AlwaysRefresh)\n    --刷新字符串\n    \n    if(RN('ClearLog')==true)then\n            SN.log=''\n            SN.PeopleList={}\n            SN.PeopleListTotal={}\n            SN.PeopleListSort={}\n            \n        end\n        \n        \n        if(SN.NeedRefresh==true or AlwaysRefresh==true )then\n            --if(true)then\n            SN.NeedRefresh=false\n            local paper='吃蓝统计如下：\\n'\n            --显示补助说明\n            \n            if(DisplayMoney==true)then\n                \n                local table = RN('PotionGroup') \n                paper = paper..'补助说明:'\n                for k,v in pairs(table)do\n                    paper = paper..v.Name..'补助'..tostring(v.MONEY)..'G\\n'\n                end\n                \n                paper = paper..'\\n'\n            end\n            --根据排好序的人物表构造字符串\n            for k,v in pairs(SN.PeopleListSort) do\n                local name =v.name\n                --paper2  = paper2..name\n                paper=paper..tostring(k)..':'..GetPlayerClass(name)..' '..name..' '\n                for h,g in pairs(SN.PeopleList) do\n                    if(h==name)then\n                        for l,j in pairs(g) do \n                            --paper2  = paper2..l..tostring(j)\n                            paper = paper..l..': '..tostring(j)..'个 '  \n                        end\n                        if(DisplayMoney==true)then\n                            local count=0\n                            for z,x in pairs(g)do\n                                --l为药名,j为数量\n                                local mmm = FindPotionMoney(z)\n                                --print('价格为：',mmm)\n                                count=count+FindPotionMoney(z)*x\n                                \n                            end\n                            paper = paper.. ' 总共'..tostring( count)..'G'\n                        end\n                        paper = paper..'\\n'\n                    end\n                    \n                end\n            end\n            --[[\n        --显示各个人的补助\n        for k,v in pairs(SN.PeopleList) do\n            --第一层循环是人名    \n            paper=paper..GetPlayerClass(k)..' '..k..' '\n            \n            --第二层是各个药剂名称\n            for l,j in pairs(v)do\n                paper = paper..l..': '..tostring(j)..'个 '  \n            end\n            if(DisplayMoney==true)then\n                local count=0\n                for z,x in pairs(v)do\n                    --l为药名,j为数量\n                    local mmm = FindPotionMoney(z)\n                    --print('价格为：',mmm)\n                    count=count+FindPotionMoney(z)*x\n                    \n                end\n                paper = paper.. ' 总共'..tostring( count)..'G'\n            end\n            paper = paper..'\\n'\n        end\n        --]]\n            SN.log = paper\n            \n        end\n        \n        if(RN('DisplayLog')==true)then\n            return '吃蓝监控日志\\n'..SN.log..date (\"%Y-%m-%d %H:%M:%S\")\n        else\n            return ''\n        end\n    end\n    \n    \n    \n    ",
["yOffset"] = -18.4799194335938,
["anchorPoint"] = "CENTER",
["displayText_format_1.spellName_format"] = "none",
["displayText_format_p_time_format"] = 0,
