},
["init"] = {
["custom"] = "--EMPS EAT MANA POTION STATISTICS --吃蓝药统计\nlocal clear=false\nif(EMPS==nil  or clear )then\n    EMPS={\n        PeopleList={\n            \n        },\n        PeopleListTotal={\n            \n        }\n        ,PeopleListSort={}\n        ,log='' -- 显示给玩家的日志字符串\n        ,EncounterDate=''\n        ,LastLog='' --上次日志\n        ,InCombat=false\n        ,NeedRefresh=false --需要刷新\n        ,TotalLog=''\n    }\n    \n    \nend\n\n\n",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "BCMD.LastLog =BCMD.LastLog ..'\\n'.. BCMD.log --拼接历史记录",
