},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "timed",
["spellIds"] = {
},
["events"] = "CLEU:SPELL_ENERGIZE",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["custom_type"] = "event",
["custom"] = "--2020年9月16日13:19:47\n--v0.0.6\n--修改清空日志的BUG\n\n--2020年9月13日22:13:49\n--v0.0.5\n--修改清空日志的BUG\n\n--2020年9月10日01:12:27\n--v0.0.4\n--增加吃药排序\n\n--2020年9月9日19:22:23\n--v0.0.3\n--增加了一个立刻清楚日志的功能，请在清除日志\n\n--2020年9月3日19:56:09\n--v0.0.2\n--增加了团队通报\n\nfunction(event,...)\n    --合成出aura_env.config里面的配置变量名称，并返回该值\n    function RN(name)\n        if(type(name)~='string')\n        then\n            return nil    \n        end\n        \n        local ac = aura_env.config\n        local SNV = 'EMPS.' --本WA的配置参数前缀缩写\n        local ccc = ac[SNV..name]\n        return ccc\n    end\n    local SN=EMPS --本WA的全局变量前缀缩写\n    \n    if(event=='COMBAT_LOG_EVENT_UNFILTERED')then\n        --print(event,select(1,...))\n        local offset=-1\n        \n        local subevent = select(offset+3,...)\n        if(subevent=='SPELL_ENERGIZE')then\n            \n            local sourceGUID ,sourceName,destGUID,destName=select(offset+5,...),select(offset+6,...),select(offset+9,...),select(offset+10,...)\n            local skillName,amout,overamount =select(offset+14,...),select(offset+16,...),select(offset+17,...)\n            local total = amout+overamount \n            local powertype = select(offset+18,...)\n            --吃特效法力药水事件\n            local EatPotion=false\n            local ManaPotionName=''\n            --返回玩家职业\n            function GetPlayerClass(Name)\n                local playerclass=''\n                local index=1\n                local gp=''\n                for unit in WA_IterateGroupMembers() do\n                    --查询玩家的信息\n                    local Pname, rank, subgroup, level, class, fileName, \n                    zone, online, isDead, role, isML, combatRole=GetRaidRosterInfo(index)\n                    if(Pname== Name)\n                    then\n                        \n                        playerclass =  tostring(subgroup)..'队的'..class\n                    end\n                    index = index+1\n                end\n                \n                return playerclass\n            end\n            if(skillName=='恢复法力' and total>=1350 )then\n                EatPotion=true\n                ManaPotionName = '特效法力药水'\n            elseif(skillName=='黑暗符文' or skillName=='恶魔符文' and powertype==0)then\n                EatPotion=true\n                ManaPotionName = skillName\n            end\n            \n            \n            if(EatPotion==true)then\n                if(SN.PeopleList==nil)then\n                    SN.PeopleList={}    \n                    \n                end\n                if(SN.PeopleList[sourceName]==nil)then\n                    SN.PeopleList[sourceName]={}    \n                end\n                if(SN.PeopleList[sourceName][ManaPotionName]==nil)then\n                    SN.PeopleList[sourceName][ManaPotionName]=1   \n                else\n                    SN.PeopleList[sourceName][ManaPotionName]=SN.PeopleList[sourceName][ManaPotionName]+1\n                end\n                --对吃药统计数据进行排序\n                SN.PeopleListSort={}\n                for k,v in pairs(SN.PeopleList) do\n                    local sum=0\n                    for l,j in pairs(v) do\n                        sum = sum+j\n                    end\n                    local aa={name=k,sum=sum}\n                    table.insert(SN.PeopleListSort,aa)\n                end\n                \n                table.sort( SN.PeopleListSort,function(a,b)\n                        return    a.sum>b.sum\n                    end \n                )\n                \n                local str = tostring(SN.PeopleList[sourceName][ManaPotionName])\n                local num=0 --寻找排名\n                for k,v in pairs(SN.PeopleListSort) do\n                    if(v.name==sourceName)    then\n                        num=k\n                    end\n                end\n                \n                local paper = GetPlayerClass(sourceName)..' '..sourceName..'使用了 '..ManaPotionName\n                if(num>0)then\n                    paper = paper..'，总使用次数：'.. str ..'，排名:'..tostring(num)\n                end\n                --通知立刻刷新字符串\n                SN.NeedRefresh = true\n                if(RN('TellInRaid')==true)then\n                    SendChatMessage(paper, \"Raid\")           \n                end\n            end\n        end\n    end\n    return true\nend\n\n\n",
