["wagoID"] = "6HHBMDHTD",
["parent"] = "法师牧师盾右侧半圆 右边-载入-从不去掉自行开启关闭-7.6",
["displayText_format_p_time_dynamic_threshold"] = 0,
["customText"] = "",
["shadowYOffset"] = -1,
