["custom"] = "function( event, ...)\n    if event == \"PLAYER_ENTERING_WORLD\" or event == \"UNIT_INVENTORY_CHANGED\" then --doesn't return valid durations without C_Timer     \n        C_Timer.After(0.1, function()\n                WeakAuras.ScanEvents(\"ITEM_ENCH_TG\")            end\n        )        \n    elseif event == \"ITEM_ENCH_TG\" and not WeakAuras.IsOptionsOpen() then\n        local mh = GetInventoryItemLink(\"player\", 17)\n        local _, _, _, _, _, _, itemType,stype = GetItemInfo(mh)\n        --  print( itemType )\n        --   print (mh)\n        if mh  and itemType ~= \"盾牌\" then\n            \n            return true  \n            \n        end\n    end\nend",
