["events"] = "MODIFIER_STATE_CHANGED CHAT_MSG_ADDON",
["custom"] = "function(event,subEvent,state)\n    if (not UnitIsGroupAssistant(\"player\")) and (not UnitIsGroupLeader(\"player\")) then return end\n    if event == \"MODIFIER_STATE_CHANGED\" then\n        if aura_env.config.com1 then\n            if state == 1 then\n                aura_env.MSC[subEvent] = true\n            else\n                aura_env.MSC[subEvent] = false\n            end \n            local match = true\n            for k,v in pairs(aura_env.MSC) do\n                if aura_env.config.MSC[k] ~= v then\n                    match = false\n                    break\n                end\n            end\n            if match then\n                WeakAuras.ScanEvents(\"CRAM_CLEAR\",true)\n            end\n        end\n    elseif event == \"CHAT_MSG_ADDON\"  and subEvent == \"CRAM_CLEAR\" then\n        WeakAuras.ScanEvents(\"CRAM_CLEAR\",true)\n    end\n    return true\nend\n\n\n\n",
