["finish"] = {
},
["init"] = {
["custom"] = "aura_env.GetPriority = function(npcId)\n    local priority = {}\n    local cache = {}\n    for i = 1,8 do\n        cache[i] = true\n    end\n    for i = 1,8 do\n        local j = tostring(i)\n        if aura_env.config[npcId][j] > 1 then\n            priority[i] = 10 - aura_env.config[npcId][j]\n            cache[9-i] = false\n        end\n    end\n    for i = 1,8 do\n        if not priority[i] then\n            for j = 8,1,-1 do\n                if cache[j] then\n                    priority[i] = j\n                    cache[j] = false\n                    break\n                end\n            end\n        end\n    end\n    return priority\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["events"] = "UPDATE_MOUSEOVER_UNIT",
["custom"] = "function(event,...)\n    if (not UnitIsGroupAssistant(\"player\")) and (not UnitIsGroupLeader(\"player\")) then return end\n    if event == \"UPDATE_MOUSEOVER_UNIT\" then\n        if UnitIsPlayer(\"mouseover\") or UnitIsDead(\"mouseover\")  or (not UnitGUID(\"mouseover\")) or (not UnitName(\"mouseover\")) then return end\n        local GUID,name = UnitGUID(\"mouseover\"),UnitName(\"mouseover\")\n        local npcId = \"\"\n        local priority = {}\n        npcId = select(6,strsplit(\"-\",GUID))\n        if aura_env.config[npcId] and aura_env.config[npcId].enabled then\n            priority = aura_env.GetPriority(npcId)\n            if not GetRaidTargetIndex(\"mouseover\") then\n                if  IsMounted()  then\n                    if aura_env.config[npcId].mounted then\n                        WeakAuras.ScanEvents(\"CRAM_MARK\",GUID,name,priority,aura_env.config[npcId].mountedLimit)\n                    end\n                else\n                    WeakAuras.ScanEvents(\"CRAM_MARK\",GUID,name,priority,aura_env.config[npcId].limit)\n                end\n                return true\n            end\n        end\n    end\nend",
