["displayText"] = "%c",
["customText"] = "function()\n    local v = aura_env.var\n    if not v then return \"加载中...\" end\n    \n    local inInst, instType = IsInInstance()\n    local isNowIn = inInst and (instType == \"party\" or instType == \"raid\")\n    local xp_cur, xp_max = UnitXP(\"player\"), UnitXPMax(\"player\")\n    \n    -- --- [ 1. 结算通报逻辑 ] ---\n    if v[\"trigger_settle\"] then\n        v[\"trigger_settle\"] = false \n        local isDebug = v[\"saved_debug\"]\n        local current_exp = v[\"total_exp\"] or 0\n        local current_kill = v[\"kill_count\"] or 0\n        local current_time = v[\"total_time\"] or 0\n        \n        if current_exp > 0 or isDebug then\n            local t_min, t_sec = math.floor(current_time/60), math.floor(current_time%60)\n            local str_times = (current_exp > 0) and string.format(\"%.1f\", (xp_max - xp_cur) / current_exp) or \"-\"\n            \n            local msg = string.format(\"副本结算: 第%d次 / 用时 %02u:%02u / 杀怪 %d / 经验 %d / 还需 %s次\", \n                v[\"num\"] or 0, t_min, t_sec, current_kill, current_exp, str_times)\n            \n            -- 本地彩色版：同步糖果天蓝 ff00bfff\n            local cMsg = string.format(\"|cfffffffff副本结算:|r 第|cffffd93d%d|r次 / 用时 |cffffd93d%02u:%02u|r / 杀怪 |cff6bff6b%d|r / 经验 |cff6bff6b%d|r / 还需 |cffffffff%s|r次\", \n                v[\"num\"] or 0, t_min, t_sec, current_kill, current_exp, str_times)\n            \n            local mode = v[\"saved_mode\"] or 4\n            if mode == 2 and IsInGroup() then\n                SendChatMessage(msg, IsInRaid() and \"RAID\" or \"PARTY\")\n            elseif mode == 3 then\n                SendChatMessage(msg, \"WHISPER\", nil, UnitName(\"player\"))\n            elseif mode ~= 1 then\n                print(cMsg)\n            end\n        else\n            print(\"|cffaaaaaa[ExpHelper] 获取经验为0，跳过通报|r\")\n        end\n        v[\"last_exp\"], v[\"last_kill\"], v[\"last_time\"] = current_exp, current_kill, current_time\n        v[\"total_exp\"], v[\"kill_count\"], v[\"total_time\"] = 0, 0, 0\n    end\n    \n    -- --- [ 2. 运行统计逻辑 ] --- \n    if isNowIn then\n        if not v[\"flag_old_in\"] then\n            v[\"num\"] = (v[\"num\"] or 0) + 1\n            v[\"start_time\"] = GetTime()\n            v[\"total_exp\"], v[\"kill_count\"], v[\"total_time\"] = 0, 0, 0\n        end\n        v[\"total_time\"] = GetTime() - (v[\"start_time\"] or GetTime())\n        v[\"flag_old_in\"] = true\n    else\n        v[\"flag_old_in\"] = false\n    end\n    \n    -- --- [ 3. 显示渲染 ] --- \n    local d_exp = isNowIn and (v[\"total_exp\"] or 0) or (v[\"last_exp\"] or 0)\n    local d_kill = isNowIn and (v[\"kill_count\"] or 0) or (v[\"last_kill\"] or 0)\n    local d_time = isNowIn and (v[\"total_time\"] or 0) or (v[\"last_time\"] or 0)\n    \n    local needed_pct = (xp_max - xp_cur) / (xp_max > 0 and xp_max or 1)\n    local str_pct = string.format(\"%.2f\", needed_pct * 100)\n    local render_times = (d_exp > 0) and string.format(\"%.1f\", (xp_max - xp_cur) / d_exp) or \"-\"\n    \n    -- --- 奶油色系 ---\n    local cTitle  = \"ff00bfff\" -- 糖果天蓝\n    local cYellow = \"ffffd93d\" -- 暖阳黄\n    local cGreen  = \"ff6bff6b\" -- 青柠绿\n    local cWhite  = \"ffffffff\" -- 纯白\n    \n    -- 渐变逻辑：从 樱花粉 (ff85a1) 到 青柠绿 (6bff6b)\n    local r1, g1, b1 = 255, 133, 161 -- 樱花粉\n    local r2, g2, b2 = 107, 255, 107 -- 青柠绿\n    \n    local r = r1 + (r2 - r1) * (1 - needed_pct)\n    local g = g1 + (g2 - g1) * (1 - needed_pct)\n    local b = b1 + (b2 - b1) * (1 - needed_pct)\n    \n    local cPct = string.format(\"ff%02x%02x%02x\", r, g, b)\n    \n    return string.format(\n        \"|c%s副本次数:|r |c%s%d|r\\n\" ..\n        \"|c%s副本用时:|r |c%s%02d:%02d|r\\n\" ..\n        \"|c%s杀怪数量:|r |c%s%d|r\\n\" ..\n        \"|c%s获得经验:|r |c%s%d|r\\n\" ..\n        \"|c%s每秒效率:|r |c%s%u|r\\n\" ..\n        \"|c%s升级还需:|r |c%s%s%%|r |c%s%s次|r\",\n        cTitle, cYellow, v[\"num\"] or 0,\n        cTitle, cYellow, d_time/60, d_time%60,\n        cTitle, cGreen, d_kill,\n        cTitle, cGreen, d_exp,\n        cTitle, cGreen, d_exp/(d_time>0 and d_time or 1),\n        cTitle, cPct, str_pct, cWhite, render_times\n    )\nend",
["yOffset"] = -120,
["anchorPoint"] = "CENTER",
["customTextUpdate"] = "update",
["url"] = "",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["do_custom"] = true,
["custom"] = "aura_env.var = aura_env.var or {}\nlocal v = aura_env.var\n\n-- 1. 基础数据\nv[\"num\"] = v[\"num\"] or 0\nv[\"kill_count\"] = v[\"kill_count\"] or 0\nv[\"total_exp\"] = v[\"total_exp\"] or 0\nv[\"total_time\"] = v[\"total_time\"] or 0\n\n-- 2. 预存配置\nlocal cfg = aura_env.config or {}\nv[\"saved_mode\"] = cfg[\"send_exp\"] or 4\nv[\"saved_debug\"] = cfg[\"isdebug\"] or false\nv[\"saved_mouse\"] = cfg[\"mouse_reset\"] or 1\nv[\"saved_resetNum\"] = cfg[\"isResetNum\"] or false\n\n-- 3. 按钮创建与拖动\nlocal region = WeakAuras.GetRegion(aura_env.id)\nlocal btnName = \"ExpHelper_FinalBtn\"\nlocal btn = _G[btnName] or CreateFrame(\"Button\", btnName, region)\nbtn:SetParent(region)\nbtn:SetAllPoints(region)\nbtn:EnableMouse(true)\nbtn:SetFrameStrata(\"TOOLTIP\")\n\nbtn:SetScript(\"OnUpdate\", function(self)\n        if WeakAuras.IsOptionsOpen() then\n            if self:IsMouseEnabled() then self:EnableMouse(false) end\n        else\n            if not self:IsMouseEnabled() then self:EnableMouse(true) end\n        end\nend)\n\nbtn:SetScript(\"OnMouseDown\", function(self, button)\n        region:SetAlpha(0.2)\n        local m = {\"LeftButton\", \"MiddleButton\", \"RightButton\", \"Button4\", \"Button5\"}\n        local targetName = m[v[\"saved_mouse\"]] or \"LeftButton\"\n        \n        if button == targetName then\n            if v[\"saved_resetNum\"] then v[\"num\"] = 0 end\n            v[\"kill_count\"], v[\"total_exp\"], v[\"total_time\"] = 0, 0, 0\n            v[\"last_exp\"], v[\"last_kill\"], v[\"last_time\"] = 0, 0, 0\n            v[\"trigger_settle\"] = false\n            print(\"|cff00ff00[ExpHelper] 数据重置成功|r\")\n        else\n            print(\"|cffff0000[ExpHelper]|r 当前按下:\"..button..\" (重置设定:\"..targetName..\")\")\n        end\nend)\nbtn:SetScript(\"OnMouseUp\", function() region:SetAlpha(1.0) end)",
},
