["custom"] = "function(event, arg1)\n    aura_env.var = aura_env.var or {}\n    local v = aura_env.var\n    \n    -- 1. 抓取经验\n    if event == \"CHAT_MSG_COMBAT_XP_GAIN\" and arg1 then\n        v[\"kill_count\"] = (v[\"kill_count\"] or 0) + 1\n        local gain = tonumber(string.match(arg1, \"%d+\")) or 0\n        v[\"total_exp\"] = (v[\"total_exp\"] or 0) + gain\n    end\n    \n    -- 2. 状态检测（登录或切换区域）\n    local inInst, instType = IsInInstance()\n    -- 核心：只有类型为 'party' 或 'raid' 才视为副本\n    local isNowIn = inInst and (instType == \"party\" or instType == \"raid\")\n    \n    -- 检测出本动作\n    if v[\"last_in_state\"] == true and isNowIn == false then\n        v[\"trigger_settle\"] = true -- 标记：需要结算\n    end\n    \n    -- 更新当前状态\n    v[\"last_in_state\"] = isNowIn\n    \n    return true\nend",
