["彩虹鼠标-从不去掉打开"] = {
["wagoID"] = "RzZVq4F1a",
["xOffset"] = 0,
["preferToUpdate"] = false,
["yOffset"] = 0,
["anchorPoint"] = "TOP",
["url"] = "",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "local MaxSpacing = aura_env.config.dotdistance\nlocal duration = aura_env.config.lifetime\nlocal ElementCap = aura_env.config.maxdots\nlocal onlyincombat = aura_env.config.combatoption\nlocal cursorLayer = aura_env.config.cursorlayer\nlocal rainbowx = aura_env.config.changeWithTime\nlocal colourspeed = aura_env.config.colourspeed\n\nlocal LastX, LastY = GetCursorPosition()\nlocal colour1 = aura_env.config.colour1\nlocal colour2 = aura_env.config.colour2\nlocal colour3 = aura_env.config.colour3\nlocal colour4 = aura_env.config.colour4\nlocal colour5 = aura_env.config.colour5\nlocal colour6 = aura_env.config.colour6\nlocal colour7 = aura_env.config.colour7\nlocal colour8 = aura_env.config.colour8\nlocal colour9 = aura_env.config.colour9\nlocal colour10 = aura_env.config.colour10\n\nlocal blendmode\nif aura_env.config.blendmode == 1 then\n    blendmode = \"ADD\"\nelseif aura_env.config.blendmode == 2 then\n    blendmode = \"DISABLE\"\nend\n\nif not aura_env.startTime then\n    aura_env.startTime = GetTime()\nend\n\nlocal cursorLayer\nif aura_env.config.cursorlayer == 1 then\n    cursorLayer = \"TOOLTIP\"\nelseif aura_env.config.cursorlayer == 2 then\n    cursorLayer = \"BACKGROUND\"\nend\n\nlocal numPhases = aura_env.config.phasecount\nlocal phaseColors = {\n    colour1,\n    colour2,\n    colour3,\n    colour4,\n    colour5,\n    colour6,\n    colour7,\n    colour8,\n    colour9,\n    colour10\n}\n\nlocal function TimeBasedTransitionColor(startTime)\n    local elapsedTime = GetTime() - startTime\n    local cycleDuration = colourspeed\n    local phaseDuration = cycleDuration / numPhases\n    local phaseProgress = (elapsedTime % cycleDuration) / phaseDuration\n    local currentPhase = math.floor(phaseProgress)\n    local nextPhase = (currentPhase + 1) % numPhases\n    local phaseFraction = phaseProgress - currentPhase\n    \n    currentPhase = (currentPhase % numPhases) + 1\n    nextPhase = (nextPhase % numPhases) + 1\n    \n    -- Reverse the phase order\n    local r1, g1, b1 = unpack(phaseColors[nextPhase])\n    local r2, g2, b2 = unpack(phaseColors[currentPhase])\n    local r = r2 + (r1 - r2) * phaseFraction\n    local g = g2 + (g1 - g2) * phaseFraction\n    local b = b2 + (b1 - b2) * phaseFraction\n    \n    return r, g, b\nend\n\nlocal function TransitionColor(remainingDuration, totalDuration)\n    local phaseProgress = (1 - remainingDuration / totalDuration) * numPhases\n    local currentPhase = math.min(math.floor(phaseProgress), numPhases - 1)\n    local nextPhase = math.min(currentPhase + 1, numPhases - 1)\n    local phaseFraction = phaseProgress - currentPhase\n    local r1, g1, b1 = unpack(phaseColors[currentPhase + 1])\n    local r2, g2, b2 = unpack(phaseColors[nextPhase + 1])\n    local r = r1 + (r2 - r1) * phaseFraction\n    local g = g1 + (g2 - g1) * phaseFraction\n    local b = b1 + (b2 - b1) * phaseFraction\n    \n    return r, g, b\nend\n\nif not aura_env.elements then\n    aura_env.elements = {}\n    aura_env.elementsGenerated = {}\n    local tooltipStrataFrame = CreateFrame(\"Frame\", nil, UIParent)\n    tooltipStrataFrame:SetFrameStrata(cursorLayer)\n    \n    for i = 1, ElementCap do\n        local element = tooltipStrataFrame:CreateTexture(nil, \"OVERLAY\")\n        element:Hide()\n        aura_env.elements[i] = element\n    end\nend\n\n-- Trail function\naura_env.Trail = function(self)\n    \n    if WeakAuras.IsOptionsOpen() then return end\n    \n    local elapsed = self.present and GetTime() - self.present or 0\n    self.present = GetTime()\n    \n    local isInCombat = UnitAffectingCombat(\"player\")\n    if (onlyincombat and isInCombat) or not onlyincombat then\n        local PresentCursorX, PresentCursorY = GetCursorPosition()\n        local Scale = UIParent:GetEffectiveScale()\n        PresentCursorX, PresentCursorY = PresentCursorX / Scale, PresentCursorY / Scale\n        \n        local xDiff = PresentCursorX - LastX\n        local yDiff = PresentCursorY - LastY\n        local distance = math.sqrt(xDiff * xDiff + yDiff * yDiff)\n        local referenceAuraRegion = WeakAuras.GetRegion(aura_env.id)\n        if not referenceAuraRegion then \n            return \n        end\n        \n        -- 狂乱魔兽原创代码-未经允许不得转载\n        local refTexture = referenceAuraRegion.texture.texture:GetTexture()\n        \n        if distance >= MaxSpacing then\n            local steps = math.floor(distance / MaxSpacing)\n            for i = 1, steps do\n                if #aura_env.elements > 0 then\n                    local ratio = i / steps\n                    local elementX = LastX + xDiff * ratio\n                    local elementY = LastY + yDiff * ratio\n                    \n                    local element = table.remove(aura_env.elements)\n                    aura_env.elementsGenerated[#aura_env.elementsGenerated + 1] = element\n                    \n                    element.duration = duration\n                    element:SetTexture(refTexture)\n                    \n                    element:SetSize(Scale, Scale)\n                    element:SetBlendMode(blendmode)\n                    element:SetPoint(\"CENTER\", UIParent, \"BOTTOMLEFT\", elementX, elementY)\n                    element:Show()\n                end\n            end\n            LastX, LastY = PresentCursorX, PresentCursorY\n        end\n    end\n    for i, element in ipairs(aura_env.elementsGenerated) do\n        element.duration = element.duration - elapsed\n        if element.duration < 0.05 then\n            element:Hide()\n            aura_env.elements[#aura_env.elements + 1] = table.remove(aura_env.elementsGenerated, i)\n        else\n            local ElementScale = math.max(0.1, element.duration / duration)\n            local alpha = aura_env.config.Alphax * (element.duration / duration)\n            element:SetSize(aura_env.config.widthx * ElementScale, aura_env.config.heightx * ElementScale)\n            element:SetAlpha(alpha)\n            \n            if rainbowx then \n                local r, g, b = TimeBasedTransitionColor(1 - element.duration)\n                element:SetVertexColor(r, g, b, alpha)\n            end\n            if not rainbowx then \n                local r, g, b = TransitionColor(element.duration, duration)\n                element:SetVertexColor(r, g, b, alpha)\n            end\n        end\n    end\nend",
["do_custom"] = true,
},
},
